-- -----------------------------------------------------------------------------
-- Préstamo
--
-- 15.000 € a 60 meses al TAN 6 %, que dan una cuota de 290 € exactos. Es el
-- mismo préstamo que usan los tests de `src/lib/prestamos.test.ts`, para que el
-- repo no tenga tres números distintos dando vueltas.
--
-- `capital_pendiente` NO lo usa la app: se deriva de `pagos_prestamo`. Está
-- solo informativo porque el INSERT lo necesita (es NOT NULL). Con las 8 cuotas de
-- abajo sale 13.249,60 €:
--
--   cuota 1 (2026-03-28): interes 75,00 · amortiza 215,00 · queda 14.785,00
--   cuota 2 (2026-04-28): interes 73,93 · amortiza 216,07 · queda 14.568,93
--   cuota 3 (2026-05-28): interes 72,84 · amortiza 217,16 · queda 14.351,77
--   cuota 4 (2026-06-28): interes 71,76 · amortiza 218,24 · queda 14.133,53
--   cuota 5 (2026-07-28): interes 70,67 · amortiza 219,33 · queda 13.914,20
--   cuota 6 (2026-08-28): interes 69,57 · amortiza 220,43 · queda 13.693,77
--   cuota 7 (2026-09-28): interes 68,47 · amortiza 221,53 · queda 13.472,24
--   cuota 8 (2026-10-28): interes 67,36 · amortiza 222,64 · queda 13.249,60
--
-- Y 8 pagadas + 52 que quedan = 60, sin que el redondeo obligue a pagar una más.
-- -----------------------------------------------------------------------------
insert into public.prestamos (
  id, nombre, capital_inicial, capital_pendiente, cuota, fecha_inicio,
  interes_anual, interes_modo, numero_cuotas, cuenta_origen, categoria_id, notas
) values (
  '33333333-3333-4333-8333-333333333333',
  'Préstamo de ejemplo',
  15000.00,
  13249.60,
  290.00,
  date '2026-02-28',
  6.000,
  'tan',
  60,
  '11111111-1111-4111-8111-111111111111',
  '22222222-2222-4222-8222-000000000013',
  'Cuota fija de 290 € el día 28. TAN 6 %. Datos inventados para la demo.'
)
on conflict (id) do nothing;

